5	int64_t get_workspace_size(
6	    int64_t T_total,
7	    int64_t H,
8	    int64_t N = 1
9	) {
10	    constexpr int CHUNK = 16;
11	    constexpr int D = 128;
12	
13	    // Upper bound: each of N sequences adds at most 1 extra tile vs floor division
14	    int64_t total_tiles = (T_total + CHUNK - 1) / CHUNK + N;
15	
16	    static_assert(CHUNK * D * 2 % 128 == 0, "k_decayed/q_decayed/k_restored size must be 128-byte aligned");
17	    static_assert(D * 4 % 128 == 0, "g_total size must be 128-byte aligned");
18	    static_assert(CHUNK * CHUNK * 2 % 128 == 0, "INV/Mqk size must be 128-byte aligned");
19	
20	    int64_t per_tile_bytes = 3 * CHUNK * D * 2 + D * 4 + 2 * CHUNK * CHUNK * 2;
21	
22	    // Trailing buffer for the tile prefix-sum (N+1 int32), 128-byte aligned.
23	    int64_t tile_prefix_bytes = ((N + 1) * 4 + 127) / 128 * 128;
24	
25	    return H * total_tiles * per_tile_bytes + tile_prefix_bytes;
26	}
