88	    TORCH_CHECK(k.dim() == 4, "k must be [B, T, H, D]");
89	    TORCH_CHECK(v.dim() == 4, "v must be [B, T, H, D]");
90	    TORCH_CHECK(g.dim() == 4, "g must be [B, T, H, D]");
