205	        } else { \
206	            LAUNCH(true, false, false, VL); \
207	        }
208	
209	    if (is_varlen) {
210	        DISPATCH_STATE(true);
211	    } else {
212	        DISPATCH_STATE(false);
213	    }
214	
215	    #undef DISPATCH_STATE
216	    #undef LAUNCH
217	}
