45	    // TMA layouts for Kernel 2
46	    using TMAStateSmemLayout = typename K2L::TMAStateSmemLayout;
47	    using TMAFP32StateSmemLayout = typename K2L::TMAFP32StateSmemLayout;
48	
49	    // --- gmem layouts for original tensors
50	    auto gmem_layout = make_layout(make_shape(H, T_total, D), make_stride(D, D * H, 1));
51	    // 1D beta layout: [H*T] contiguous
52	    auto beta_gmem_layout = make_layout(make_shape(H * T_total));
53	    auto state_gmem_layout = make_layout(make_shape(N * H, D, D), LayoutRight{});
54	
55	    Tensor m_q   = make_tensor(make_gmem_ptr(q_ptr), gmem_layout);
56	    Tensor m_k   = make_tensor(make_gmem_ptr(k_ptr), gmem_layout);
57	    Tensor m_v   = make_tensor(make_gmem_ptr(v_ptr), gmem_layout);
